import math

# Function to find the maximum step size in S
def find_max_step_size(S):
    max_step = 0
    sorted_points = sorted(S)
    for i in range(len(sorted_points) - 1):
        x1, y1 = sorted_points[i]
        x2, y2 = sorted_points[i + 1]
        max_step = max(max_step, math.sqrt((x2 - x1)**2 + (y2 - y1)**2))
    return max_step

# Function to check if a point P is in at least one line passing through at least two points in S
def in_line(l, P):
    if (P is l[0] or P is l[1]) or (P is None):
        return True
    m, b = None, None
    for point in S:
        if point is l or point is P:
            continue
        if m is None:
            m = (point[1] - l[1]) / (point[0] - l[0])
            b = l[1] - m * l[0]
        elif m == (point[1] - l[1]) / (point[0] - l[0]) and b == l[1] - m * l[0]:
            return True
    return False

# Function to find the maximum probability of staying on the t-th point after m moves
def max_probability(t, S, P):
    q = P if P is not None else None
    max_probability = 0
    visited_points = {P} if P is not None else set()
    queue = [(0, P, 0)] if P is not None else []
    while queue:
        total_probability, point, moves = heapq.heappop(queue)
        if point is q and moves >= m:
            max_probability = max(max_probability, total_probability)
        elif point is not q:
            for neighbor in set(point) - visited_points:
                new_move_prob = (m * 1.0 / len(S)) ** ((m - moves) / m)
                if new_move_prob > 0:
                    visited_points.add(point)
                    queue.append((total_probability + (1.0 * len(S) / (len(S) - 2)), neighbor, moves + 1))
    return 1.0 - math.exp(-m / 2 / find_max_step_size(S))

