mod = 998244353

@lru_cache(maxsize=None)
def combine(s1: str, s2: str) -> List[str]:
    combine_cache = set()
    for i in range(len(s1)):
        for j in range(i + 1, len(s1) + 1):
            combine_cache.add(s1[:i] + s2 + s1[j:])
    return combine_cache

@lru_cache(maxsize=None)
def getNext(s: str, stack_stack: List[str]) -> List[str]:
    valid = []
    if "*" not in stack_stack:
        valid.extend(combine(s, st) for st in stack_stack)
    else:
        combos = set()
        stacks = set([st for st in stack_stack if "*" in st])
        for next in s[1:-1]:
            for st in stacks:
                if next != "*":
                    new_st = st.replace("*", next)
                combos.add(new_st)
            next_index = s.index("*") + 1
            for st in stacks:
                if next_index + 1 < len(s):
                    new_st = st[:next_index] + s[next_index + 1:] + st[next_index + 1:]
                combos.add(new_st)
        valid = [st for st in combos if len(*combinations) == len(stack_stack)]
        valid = combinations(sorted(valid))
    return valid

def sum_gen(stack_stack: List[str]) -> int:
    for ops in product(range(2), repeat=len(stack_stack)):
        tmp = stack_stack.copy()
        for ii in range(len(tmp)):
            if ops[ii] == 1:
                tmp[ii] = getNext(tmp[ii], tmp[:ii] + [str(ii)] + tmp[(ii + 1):])
        maansu = 0
        for t in tmp:
            maansu += len(t) - 1
        maansu %= mod
        yield maansu

def solve(in_string: str) -> int:
    stack_stack = in_string.split("*")
    stack_stack = [st.replace("*", "0") for st in stack_stack]
    ret = sum_gen(stack_stack)
    return sum(ret)

