from math import gcd

def catchMouse(m, x):
    # Reduce x and m modulo 10^6 to avoid overflow
    x = x % 10**6
    m = m % 10**6

    # Possible traps
    possible_traps = set(range(m))

    # Reduce possibilities by room x | i
    reduced_possibles = {}

    for trap in possible_traps:
        factor = gcd(x, trap)
        reduced_possibles[factor] = reducInt(factor, trap)

    # Shortest path length from any trap to an uncovered room i so far is distance of the furthest factorial
    furthest = 0

    for trap, pos in reduced_possibles.items():
        if pos > furthest:
            furthest = pos

    # The total distance from the trap to its furthest uncovered room i plus traps x*i is the navigation distance
    total_distance = m - coefficient(2, 3, m, x)
    if total_distance < 0:
        total_distance += 1
    return int(total_distance)

def reducInt(f, a):
    # Reduce a mod f
    while a >= f:
        a -= f
    return a

def coefficient(n, x, y, carry):
    # Formula to do exponent (side step)
    return (n + (x ** carry) * (y - 1)) % m

