from math import gcd

mod = 998244353

def modpow(base, exp):
    result = 1
    base %= mod
    while exp > 0:
        if exp % 2:
            result = result * base % mod
        exp //= 2
        base = base * base % mod
    return result

def prime_factorization(n):
    factors = []
    divisor = 2
    while divisor * divisor <= n:
        if n % divisor:
            divisor += 1
        else:
            n //= divisor
            factors.append(divisor)
    if n > 1:
        factors.append(n)
    return factors

def num_divisors(dp):
    n = len(dp)
    primes = {x for x in range(2, max(dp)) if gcd(*dp) != x}
    dp = sorted(dp)
    dp.insert(0, 1)
    ways = {d: 1 for d in primes}
    ans = 1
    dp[0] **= 2
    dp[dp[0]+dp[0]] %= mod
    dp[dp[0] + dp[0] + dp[1]] = dp[dp[0] + dp[0]] * dp[dp[0] + dp[0]] % mod
    for prime in primes:
        power = 1
        curr_dp = dp
        current_sum = sum(dp)
        while current_sum % mod == curr_dp[-1] % mod:
            if curr_dp[-1] % mod == 1:
                0  # There's only one instance of the prime and no odd factor.
            else:
                power = (power * dp[-1]) % mod
                dp[-1 * power % n] %= mod
            for d in dp:
                if d % prime:
                    new_dp = curr_dp + [d, int((d * d - curr_dp[-1] * curr_dp[-1]) / (d * prime))]
                    dp += [new_dp[0] + new_dp[1]]
                    for i in range(n):
                        if new_dp[0] % (i + 1) != 0 or new_dp[1] % (i + 1) != 0:
                            dp.pop()
            if len(dp) == 2:
                if (dp[1] * dp[0]) % 2 != 0:
                    dp.popleft()
                else:
                    dp.pop()
            current_sum = sum(dp)
        dp = curr_dp
        ans *= ways[prime]
        ans = ans * (1 + modpow(prime, power-1)) % mod
    return ans

