def has_cycle(graph):
    n = len(graph)
    visited = [False] * n
    recursion_stack = [False] * n
    def dfs(vertex):
        visited[vertex] = True
        recursion_stack[vertex] = True
        for neighbor in range(n):
            if graph[vertex][neighbor] == 1 and not visited[neighbor] and not recursion_stack[neighbor]:
                if dfs(neighbor):
                    return True
        recursion_stack[vertex] = False
        return False

    for vertex in range(n):
        if not visited[vertex]:
            if dfs(vertex):
                return True
    return False

def max_edges(graph):
    if has_cycle(graph):
        max_added = 0
        for vertex1 in range(len(graph)):
            if not visited[vertex1]:
                for vertex2 in range(len(graph)):
                    if not visited[vertex2]:
                        current_graph = graph.copy()
                        current_graph[vertex1][vertex2] = 1
                        if not has_cycle(current_graph):
                            max_added += 1
                            break
    else:
        max_added = len(graph) - graph[::-1].index([[1]*len(graph)])[0][0]
