    """
    Counts the number of matchable permutations for given patterns.

    :param patterns: List of patterns as strings
    :return: Number of matchable permutations
    """
    pattern_frequencies = defaultdict(int)
    for pattern in patterns:
        for c in pattern:
            pattern_frequencies[c] += 1

    matches = {}
    for c in pattern_frequencies:
        if pattern_frequencies[c] > 1:
            matches.setdefault(pattern_frequencies[c], [0, 0]).append(c)

    answer = 1
    remainder = 1
    for i in range(1, 1001):
        divisible_by_match_in = 0
        divisible_by_match_out = 0
        for c in matches[i]:
            count = pattern_frequencies[c]
            if c in matches:
                for match in matches[c]:
                    count += regex[match][i]
            if count % 2 == 1:
                divisible_by_match_in += 1
            remainder += count - 1
            remainder %= 2 * (1000 - i) + 1
            divisible_by_match_out += 1
            if remainder <= 0:
                answer *= (1000 - i) + 1
                break
