from functools import lru_cache

# Function to check if a number is a perfect square
def is_perfect_square(n):
    return int(sqrt(n)) ** 2 == n

# Function to count right permutations using dynamic programming and hashing
@lru_cache(maxsize=None)
def count_right_permutations(n, A):
    @lru_cache(maxsize=None)
    def dp(pos, left):
        if pos == n:
            return (0, 1)  # If all elements are placed, only one permutation is valid
        right_at_i_prev = 0  # Count of valid right prefix ending at i-1
        for i in range(n):
            if A[i] == pos:
                right_at_i_prev += 1
                continue
            elif i > 0 and A[i-1] == pos:
                right_at_i_prev = 0  # Reset count for right prefix if the element at i-1 is replaced
            else:
                left -= 1  # Decrease left prefix's length
            if left >= right_at_i_prev:
                right_at_i = dp(pos, left - right_at_i_prev)
                if is_perfect_square(left):
                    continue  # Skip if the number of elements in left prefix is a perfect square
                else:
                    right_at_i += 1  # Increment count with valid suffix
            dp_pos = dp(pos + 1, left - right_at_i_prev)
            dp_pos[0] += right_at_i  # Add valid prefix counts
            right_at_i_prev, dp_pos[1] = dp_pos
        return dp_pos
    return dp(0, n)

