# Get the prime factorization of n into distinct primes
def get_primes(n):
    primes = []
    factors = defaultdict(int)
    while n % 2 == 0:
        factors[2] += 1
        n //= 2
    for i in range(3, int(n**0.5 + 1), 2):
        if n % i == 0:
            factors[i] += 1
            n = n // i
        else:
            continue
    if n != 1:
        factors[int(n)] += 1
    return sorted(factors)

# Compute the product of divisors
def product_of_divisors(n):
    prime_factors = get_primes(n)
    divisors = reduce(mul, map(lambda x: [x] * factors[x] + [1] * (x - 1), product(prime_factors, repeat=len(prime_factors))))
    return reduce(mul, divisors).mod(998244353)

# Compute the product of divisors whenever calculating max partial size
prime_factors_pruning = defaultdict(lambda: defaultdict(list))

def foo(lst, prev):
    i = len(lst) - 1
    solutions = []
    while i > -1 and lst[i] >= lst[prev]:
        solutions += [lst[i] * prime_factors_pruning[len(lst)][i] for i in range(prev, len(lst) - 1, -1)]
        i -= 1
    solutions.sort(reverse=True)
    return lst if len(solutions) == 0 else max(solutions)

# Get unfinished forms of n into forms with all factors greater than 1
def get_unfinished_forms(n):
    forms = []
    if n == 1: 
        forms.append(1)
    else: 
        for i in range(n + 1):
            forms += [p ** i for p in prime_factors_pruning[n]]
    return forms

