def find_maximum_cover(patterns, S):
    n = len(S)
    max_length = 0
    for pattern in patterns:
        max_length = max(max_length, len(pattern))
    sorted_patterns = sorted(patterns, key=lambda p: len(p))

    max_cover = [(3, 'abcdef'), (2, 'ab'), (1, '')]
    for pattern in sorted_patterns:
        for i in range(3, -1, -1):
            remaining = max_length - len(pattern)
            if remaining >= i:
                pattern += sorted_patterns[0][-i:]
                break
        max_cover.sort(key=lambda pp: (-len(pp), pp[1]))
        for i in reversed(range(3, -1, -1)):
            remaining = max_length - len(pattern)
            if remaining >= i:
                pattern += max_cover.pop()[1]
                break
        if remaining < i:
            max_cover.sort(key=lambda pp: (-len(pp), pp[1]))
            if max_cover[0][0] == len(pattern):
                max_cover.append((remaining, max_cover[0][1]))
            continue
        if remaining > max_length:
            max_cover.append(((1, '$.') * (remaining - 1), max_cover[0][1]))
            break
    return max_cover[:-1]

def has_patterns(patterns, S):
    max_cover = find_maximum_cover(patterns, S)
    for _, pattern in max_cover:
        if pattern.startswith('$.'):
            return True
    return False

def count_matchable_permutations(N, M, patterns):
    S = input().strip()
    if has_patterns(patterns, S):
        return 1
    return 0

