        nodes[v].append(u)

    ancestors = [-1] * (n + 2)
    visited = [-1] * (n + 1)
    ted = [-1] * (n + 2)
    counts = [0] * (n + 2)

    product = set()
    for u in nodes:
        if not visited[u]:
            new_tree_counts = [[new_expr for new_expr in dfs(nodes, u, u, ancestors, visited, product, new_tree_counts)]]
    return len(new_tree_counts)
