def find_max_xor_length(n, S):
    if n <= 2:
        return n - 1, [0, 1] + list(range(2, 2**(n-1) + 1, 2))
    else:
        xor_result = sum(S)
        x = 0
        while xor_result > 2**x - 1:
            x += 1
        return x, [0] + sorted(S + list(range(2**x))[:-1])

n = int(input().strip())
S = list(map(int, input().strip().split()))
result_x, result_perm = find_max_xor_length(n, S)
print(result_x)
print(' '.join(map(str, result_perm)))
